// Prisma schema — edit visually in the Model Editor

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Example {
  id   String @id @default(cuid())
  name String
}

import "@typespec/http";

using TypeSpec.Http;

@service(#{ title: "My API" })
namespace MyApi;

model Item {
  @key id: string;
  name: string;
}

@route("/items")
interface Items {
  @get
  @operationId("listItems")
  list(): Item[];
}
